fn offline_recipient_lineage_operation() -> Map {
    let mut operation = Map::new();
    operation.insert(
        "tags".into(),
        Value::Array(vec![Value::String("Offline".to_owned())]),
    );
    operation.insert(
        "operationId".into(),
        Value::String("offlineRecipientLineage".to_owned()),
    );
    operation.insert(
        "summary".into(),
        Value::String("Resolve a receiver's active registration lineage.".to_owned()),
    );
    operation.insert(
        "description".into(),
        Value::String(
            "Validate one canonical device-signed KagemushaRecipientPaymentRequestV2 and return the unique current-policy, unexpired on-chain P-256 registration together with its exact committed transaction, bounded entrypoint/result Merkle proofs, admission block header, and independently verifiable historical Sumeragi-v2 finality artifact. Policy rotation, expiry, ambiguous registrations, incomplete history, and proof gaps fail closed."
                .to_owned(),
        ),
    );
    operation.insert(
        "requestBody".into(),
        Value::Object(offline_typed_request_body(
            iroha_torii_shared::offline_api::OFFLINE_RECIPIENT_LINEAGE_REQUEST_SCHEMA_NAME,
            iroha_data_model::offline::KAGEMUSHA_RECURSIVE_SPEND_MAX_PEER_ARCHIVE_BYTES_V2,
        )),
    );
    let mut responses = Map::new();
    responses.insert(
        "200".to_owned(),
        norito_binary_response(
            "The active receiver registration and its admission proofs.",
            "OfflineRecipientRegistrationLineage",
        ),
    );
    responses.insert(
        "400".to_owned(),
        dual_format_error_response_with_reject_codes(
            "The signed receiver request is malformed, expired, or targets another chain.",
            "Exact receiver-lineage request validation code.",
            &[
                "offline_receiver_lineage_request_invalid",
                "offline_receiver_lineage_chain_mismatch",
            ],
        ),
    );
    responses.insert(
        "404".to_owned(),
        dual_format_error_response_with_reject_codes(
            "No exact on-chain registration matches the signed receiver request.",
            "Exact receiver-registration resource code.",
            &["offline_receiver_not_registered"],
        ),
    );
    responses.insert(
        "409".to_owned(),
        dual_format_error_response_with_reject_codes(
            "The matching registration is expired or was admitted under a superseded policy.",
            "Exact inactive-registration code.",
            &["offline_receiver_registration_inactive"],
        ),
    );
    responses.insert("401".to_owned(), api_token_unauthorized_response());
    responses.insert("406".to_owned(), offline_not_acceptable_response());
    responses.insert(
        "429".to_owned(),
        retryable_error_response(
            "The receiver-lineage request was rejected by an ingress or route rate limit.",
            &[],
        ),
    );
    responses.insert(
        "503".to_owned(),
        retryable_error_response(
            "Canonical registration state, transaction history, or finality proof is unavailable or inconsistent.",
            &["offline_receiver_lineage_inconsistent"],
        ),
    );
    operation.insert("responses".into(), Value::Object(responses));
    let mut methods = Map::new();
    methods.insert("post".to_owned(), Value::Object(operation));
    methods
}

fn offline_readiness_operation() -> Map {
    let mut operation = Map::new();
    operation.insert(
        "tags".into(),
        Value::Array(vec![Value::String("Offline".to_owned())]),
    );
    operation.insert(
        "operationId".into(),
        Value::String("offlineReadiness".to_owned()),
    );
    operation.insert(
        "summary".into(),
        Value::String("Report Kagemusha readiness.".to_owned()),
    );
    operation.insert(
        "description".into(),
        Value::String(
            "Evaluate Kagemusha readiness for one asset definition at a specific committed block. The response binds the live asset scale, five distinct active verifier records, and exact authenticated ABI-21 V4 release identity to that same height and block hash so clients can cross-check capabilities and release artifacts atomically. proof_backend_available reports exact backend construction independently; recursive_lineage_supported additionally requires the authenticated artifact set and distinct active Eq/Ep records. ready is true exactly when no typed blocker remains, so unrelated blockers do not erase backend or lineage facts. A successfully evaluated but unavailable capability returns 200 with ready=false and typed blockers. A 503 readiness_unavailable response means Torii could not evaluate readiness."
                .to_owned(),
        ),
    );
    operation.insert(
        "parameters".into(),
        Value::Array(vec![
            norito::json!({
                "name": "asset_definition_id",
                "in": "query",
                "required": true,
                "schema": { "type": "string" },
                "description": "Canonical asset-definition address literal or currently live asset alias. The response always contains the resolved canonical asset definition id."
            }),
            norito::json!({
                "name": "If-None-Match",
                "in": "header",
                "required": false,
                "schema": { "type": "string" },
                "description": "A strong or weak ETag returned by an earlier readiness evaluation, or *. A match for the selected representation returns 304."
            }),
        ]),
    );
    let mut responses = Map::new();
    let mut ok = dual_format_response(
        "Readiness was evaluated successfully.",
        "#/components/schemas/OfflineReadiness",
    );
    if let Value::Object(response) = &mut ok {
        response.insert(
            "headers".into(),
            Value::Object(offline_readiness_response_headers()),
        );
    }
    responses.insert("200".to_owned(), ok);
    responses.insert(
        "304".to_owned(),
        norito::json!({
            "description": "The previously returned readiness representation is still current.",
            "headers": {
                "ETag": {
                    "description": "Strong validator for the selected readiness representation.",
                    "schema": { "type": "string" }
                },
                "Cache-Control": {
                    "description": "Readiness revalidation policy.",
                    "schema": { "type": "string", "example": "private, max-age=0, must-revalidate" }
                },
                "Vary": {
                    "description": "Negotiated response dimension.",
                    "schema": { "type": "string", "example": "Accept" }
                }
            }
        }),
    );
    responses.insert(
        "400".to_owned(),
        dual_format_error_response_with_reject_codes(
            "The asset selector is malformed.",
            "Exact application-validation code; transport or parser failures sharing HTTP 400 may omit this header.",
            &["asset_definition_id_invalid"],
        ),
    );
    responses.insert(
        "404".to_owned(),
        dual_format_error_response_with_reject_codes(
            "The asset definition does not exist.",
            "Exact application-resource code distinguishing a missing asset from an unmatched or intermediary-generated HTTP 404.",
            &["asset_definition_not_found"],
        ),
    );
    responses.insert("401".to_owned(), api_token_unauthorized_response());
    responses.insert("406".to_owned(), offline_not_acceptable_response());
    responses.insert(
        "429".to_owned(),
        retryable_error_response(
            "The readiness request was rejected by an ingress or route rate limit.",
            &[],
        ),
    );
    responses.insert(
        "503".to_owned(),
        retryable_error_response(
            "Torii could not evaluate readiness (readiness_unavailable).",
            &["readiness_unavailable"],
        ),
    );
    operation.insert("responses".into(), Value::Object(responses));
    let mut methods = Map::new();
    methods.insert("get".to_owned(), Value::Object(operation));
    methods
}

fn offline_async_operation(
    operation_id: &str,
    summary: &str,
    description: &str,
    norito_schema: &str,
    maximum_bytes: usize,
) -> Map {
    let mut operation = Map::new();
    operation.insert(
        "tags".into(),
        Value::Array(vec![Value::String("Offline".to_owned())]),
    );
    operation.insert("operationId".into(), Value::String(operation_id.to_owned()));
    operation.insert("summary".into(), Value::String(summary.to_owned()));
    operation.insert("description".into(), Value::String(description.to_owned()));
    operation.insert(
        "parameters".into(),
        Value::Array(vec![norito::json!({
            "name": "Idempotency-Key",
            "in": "header",
            "required": true,
            "schema": { "type": "string", "pattern": "^(?!0{64}$)[0-9a-f]{64}$" },
            "description": "Non-zero lowercase hexadecimal form of the request's signed 32-byte operation id. The identifier is globally single-use across offline command routes and binds the complete signed authorization and canonical typed request. Identical replays return the original operation; any other reuse conflicts while the original queue, process-cache, or retained-block record is recoverable. Clients must never recycle an id after a 404."
        })]),
    );
    operation.insert(
        "requestBody".into(),
        Value::Object(offline_typed_request_body(norito_schema, maximum_bytes)),
    );
    let mut responses = Map::new();
    let mut accepted = dual_format_response(
        "The command was accepted for asynchronous processing.",
        "#/components/schemas/OfflineOperationReference",
    );
    if let Value::Object(response) = &mut accepted {
        response.insert(
            "headers".into(),
            Value::Object(offline_operation_response_headers(true)),
        );
    }
    responses.insert("202".to_owned(), accepted);
    responses.insert("401".to_owned(), api_token_unauthorized_response());
    for (status, description) in [
        ("400", "The typed request is malformed."),
        (
            "403",
            "Canonical X-Iroha request-signing headers are unsupported on signed-body offline commands.",
        ),
        (
            "409",
            "The idempotency key or operation id conflicts with another request.",
        ),
        (
            "413",
            "The typed request exceeds Torii's configured transaction body limit.",
        ),
        ("415", "The request content type is missing or unsupported."),
        (
            "429",
            "The command was rejected by a Torii or transaction-queue rate limit.",
        ),
        (
            "500",
            "Torii could not read its process-local operation registry or encode the response.",
        ),
        ("503", "The operation cannot currently be accepted."),
    ] {
        let response = match status {
            "400" => {
                let codes = offline_command_bad_request_reject_codes(operation_id);
                dual_format_error_response_with_reject_codes(
                    description,
                    "Exact Torii application-validation or transaction-admission code; Content-Type, body-decoding, and body-read failures sharing HTTP 400 omit this header.",
                    &codes,
                )
            }
            "403" => dual_format_error_response_with_reject_codes(
                description,
                "Exact signed-body authorization or transaction-queue policy rejection code.",
                OFFLINE_COMMAND_FORBIDDEN_REJECT_CODES,
            ),
            "409" => dual_format_error_response_with_reject_codes(
                description,
                "Exact operation-binding or duplicate transaction-admission code.",
                OFFLINE_COMMAND_CONFLICT_REJECT_CODES,
            ),
            "429" => retryable_error_response(description, OFFLINE_COMMAND_RATE_LIMIT_REJECT_CODES),
            "503" => {
                retryable_error_response(description, OFFLINE_COMMAND_UNAVAILABLE_REJECT_CODES)
            }
            _ => dual_format_response(description, "#/components/schemas/ErrorEnvelope"),
        };
        responses.insert(status.to_owned(), response);
    }
    responses.insert("406".to_owned(), offline_not_acceptable_response());
    operation.insert("responses".into(), Value::Object(responses));
    let mut methods = Map::new();
    methods.insert("post".to_owned(), Value::Object(operation));
    methods
}

fn offline_operation_status_operation() -> Map {
    let mut operation = Map::new();
    operation.insert(
        "tags".into(),
        Value::Array(vec![Value::String("Offline".to_owned())]),
    );
    operation.insert(
        "operationId".into(),
        Value::String("offlineOperationStatus".to_owned()),
    );
    operation.insert(
        "summary".into(),
        Value::String("Fetch an offline operation.".to_owned()),
    );
    operation.insert(
        "description".into(),
        Value::String(
            "Return the current tagged state of an accepted top-up or redemption. Pending responses include Retry-After. Pending state can be recovered from the transaction queue, and committed terminal state is resolved through Kura's bounded operation-id index and exact canonical carrier, including its validated merge entry when applicable. The process-local admission registry retains only fixed-size canonical request bindings, shares configured count/byte capacity with in-flight reservations, never capacity-evicts an unexpired binding, and prunes accepted bindings 24 hours after signed authorization expiry. A 503 response means that admission capacity, index reconstruction, or indexed block/merge history is temporarily unavailable."
                .to_owned(),
        ),
    );
    operation.insert(
        "parameters".into(),
        Value::Array(vec![norito::json!({
            "name": "operation_id",
            "in": "path",
            "required": true,
            "schema": { "type": "string", "pattern": "^(?!0{64}$)[0-9a-f]{64}$" },
            "description": "Canonical non-zero lowercase hexadecimal identifier from the global offline operation namespace."
        })]),
    );
    let mut responses = Map::new();
    let mut ok = dual_format_response(
        "Current operation state.",
        "#/components/schemas/OfflineOperationStatus",
    );
    if let Value::Object(response) = &mut ok {
        response.insert(
            "headers".into(),
            Value::Object(offline_operation_response_headers(false)),
        );
    }
    responses.insert("200".to_owned(), ok);
    responses.insert("401".to_owned(), api_token_unauthorized_response());
    for (status, description) in [
        ("400", "The operation id is malformed."),
        ("404", "No such operation exists."),
        (
            "429",
            "The status request was rejected by the Torii rate limit.",
        ),
        (
            "500",
            "The process-local operation registry could not be read.",
        ),
        (
            "503",
            "The offline operation index or indexed block body is temporarily unavailable.",
        ),
    ] {
        let response = match status {
            "400" => dual_format_error_response_with_reject_codes(
                description,
                "Exact application-validation code for a malformed operation identifier.",
                &["operation_id_invalid"],
            ),
            "404" => dual_format_error_response_with_reject_codes(
                description,
                "Exact application-resource code distinguishing an unknown offline operation from an unmatched or intermediary-generated HTTP 404.",
                &["offline_operation_not_found"],
            ),
            "429" => retryable_error_response(description, &[]),
            "503" => retryable_error_response(
                description,
                OFFLINE_OPERATION_STATUS_UNAVAILABLE_REJECT_CODES,
            ),
            _ => dual_format_response(description, "#/components/schemas/ErrorEnvelope"),
        };
        responses.insert(status.to_owned(), response);
    }
    responses.insert("406".to_owned(), offline_not_acceptable_response());
    operation.insert("responses".into(), Value::Object(responses));
    let mut methods = Map::new();
    methods.insert("get".to_owned(), Value::Object(operation));
    methods
}

fn offline_typed_request_body(norito_schema: &str, maximum_bytes: usize) -> Map {
    let mut body = Map::new();
    body.insert("required".into(), Value::Bool(true));
    body.insert(
        "content".into(),
        norito::json!({
            "application/x-norito": {
                "schema": {
                    "type": "string",
                    "format": "binary",
                    "x-iroha-norito-schema": norito_schema,
                    "x-iroha-max-bytes": maximum_bytes
                }
            }
        }),
    );
    body
}

fn offline_not_acceptable_response() -> Value {
    norito::json!({
        "description": "Neither application/json nor application/x-norito is acceptable. Because no requested representation was selected, the typed response_not_acceptable error uses deterministic application/json.",
        "headers": {
            "Vary": {
                "description": "Negotiated response dimension.",
                "schema": { "type": "string", "example": "Accept" }
            }
        },
        "content": {
            "application/json": {
                "schema": { "$ref": "#/components/schemas/ErrorEnvelope" }
            }
        }
    })
}

fn retryable_error_response(description: &str, reject_codes: &[&str]) -> Value {
    let mut response = dual_format_response(description, "#/components/schemas/ErrorEnvelope");
    if let Value::Object(response) = &mut response {
        let mut headers = Map::new();
        headers.insert(
            "Retry-After".into(),
            norito::json!({
                "description": "Whole-second retry delay; the ErrorEnvelope retry_after_seconds detail carries the same value.",
                "schema": { "type": "integer", "minimum": 0 }
            }),
        );
        headers.insert(
            "Cache-Control".into(),
            norito::json!({
                "description": "Retryable failures are not cacheable.",
                "schema": { "type": "string", "example": "no-store" }
            }),
        );
        headers.insert(
            "Vary".into(),
            norito::json!({
                "description": "Negotiated response dimension.",
                "schema": { "type": "string", "example": "Accept" }
            }),
        );
        if !reject_codes.is_empty() {
            headers.extend(exact_reject_code_headers(
                "Exact Torii application or transaction-queue availability code; ingress limits sharing this status may omit the header.",
                reject_codes,
            ));
        }
        response.insert("headers".into(), Value::Object(headers));
    }
    response
}

fn api_token_unauthorized_response() -> Value {
    let mut response = dual_format_response(
        "The Torii API token is missing or invalid (api_token_required).",
        "#/components/schemas/ErrorEnvelope",
    );
    if let Value::Object(response) = &mut response {
        response.insert(
            "headers".into(),
            norito::json!({
                "WWW-Authenticate": {
                    "description": "Authentication challenge for the Torii API-token scheme.",
                    "schema": {
                        "type": "string",
                        "example": "IrohaApiToken realm=\"torii\""
                    }
                }
            }),
        );
    }
    response
}

fn offline_readiness_response_headers() -> Map {
    let mut headers = Map::new();
    headers.insert(
        "ETag".into(),
        norito::json!({
            "description": "Strong readiness validator bound to the complete selected representation and evaluated block.",
            "schema": { "type": "string" }
        }),
    );
    headers.insert(
        "Cache-Control".into(),
        norito::json!({
            "description": "Readiness responses require revalidation.",
            "schema": { "type": "string", "example": "private, max-age=0, must-revalidate" }
        }),
    );
    headers.insert(
        "Vary".into(),
        norito::json!({
            "description": "Negotiated response dimension.",
            "schema": { "type": "string", "example": "Accept" }
        }),
    );
    headers
}

fn offline_operation_response_headers(include_location: bool) -> Map {
    let mut headers = Map::new();
    if include_location {
        headers.insert(
            "Location".into(),
            norito::json!({
                "description": "Canonical operation status resource.",
                "schema": {
                    "type": "string",
                    "format": "uri-reference",
                    "pattern": "^/v1/offline/operations/(?!0{64}$)[0-9a-f]{64}$"
                }
            }),
        );
    }
    headers.insert(
        "Retry-After".into(),
        norito::json!({
            "description": "Recommended polling delay in seconds while the operation is pending.",
            "schema": { "type": "integer", "minimum": 0 }
        }),
    );
    headers.insert(
        "Cache-Control".into(),
        norito::json!({
            "description": "Operation responses are not cacheable.",
            "schema": { "type": "string", "example": "no-store" }
        }),
    );
    headers.insert(
        "Vary".into(),
        norito::json!({
            "description": "Negotiated response dimension.",
            "schema": { "type": "string", "example": "Accept" }
        }),
    );
    headers
}

